import * as THREE from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { imageUrl } = config.assets;
  const [rx, ry, rw, rh] = config.atlasRegion?.sourceRect ?? [0, 0, 512, 320];
  const placement = config.scenePlacement;

  const tex = ctx.textureLoader(imageUrl);

  const aspect = rw / rh;
  const planeHeight = 1;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const fullWidth = tex.image?.width ?? rw;
  const fullHeight = tex.image?.height ?? rh;

  const uRepeat = rw / fullWidth;
  const vRepeat = rh / fullHeight;
  const uOffset = rx / fullWidth;
  const vOffset = 1 - ((ry + rh) / fullHeight);

  const atlasUV = uv().mul(vec2(uRepeat, vRepeat)).add(vec2(uOffset, vOffset));

  const mapNode = texture(tex);
  mapNode.uvNode = atlasUV;

  const material = new THREE.MeshBasicNodeMaterial({
    map: mapNode,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  const sprite = new THREE.Mesh(geometry, material);
  sprite.position.set(placement.position.x, placement.position.y, placement.position.z);
  sprite.rotation.set(placement.rotation.x, placement.rotation.y, placement.rotation.z);
  sprite.scale.set(placement.scale.x, placement.scale.y, placement.scale.z);

  const timelines = [];

  const billboard = (renderer, scene, camera) => {
    if (camera) {
      sprite.quaternion.copy(camera.quaternion);
    }
  };

  Object.assign(sprite.userData, {
    handlers: {
      onBeforeRender: billboard,
    },
    timelines,
    cleanup: () => {
      timelines.forEach((tl) => tl && tl.kill && tl.kill());
      geometry.dispose();
      material.dispose();
    },
  });

  sprite.onBeforeRender = sprite.userData.handlers.onBeforeRender;

  return sprite;
}
